"""Build a self-contained Hebrew HTML report and its editable Markdown source.

Read existing results only; do not execute or modify vision/runtime algorithms.
"""
import base64
import html
import json
import re
import runpy
from pathlib import Path
from statistics import median

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'docs'
context = runpy.run_path(str(ROOT/'tmp/write_experiment_descriptions.py'))
descriptions = context['descriptions']
names = [f'v{i}' for i in range(1, 8)] + ['v8_landing']
data = []
for name in names:
    directory = ROOT/f'outputs/experiment_{name}'
    report = json.loads((directory/'results.json').read_text(encoding='utf-8'))
    runtime = json.loads((directory/'runtime_summary.json').read_text(encoding='utf-8'))
    video = next(e['stats'] for e in runtime['events'] if e['worker']=='Video' and e['event']=='finished')
    rows = report['frames']
    good = [r for r in rows if r['pose_valid']]
    assert len(rows)==report['processed_frames'] and len(good)==report['pose_valid_frames']
    assert all(code==0 for code in runtime['exit_codes'].values())
    graph_stats = json.loads((directory/'graphs/statistics.json').read_text(encoding='utf-8'))
    assert graph_stats['processed_frames']==len(rows) and graph_stats['pose_valid_frames']==len(good)
    data.append(dict(video=name, decoded=video['decoded_frames'], processed=len(rows),
                     pose=len(good), availability_pct=100*len(good)/len(rows),
                     losses=report['losses'], omitted=video['decoded_frames']-len(rows),
                     fps=len(rows)/report['elapsed_s'], source_fps=video['source_fps'],
                     processing_median_ms=median(r['processing_ms'] for r in rows),
                     latency_median_ms=median(r['latency_ms'] for r in rows),
                     rms_median_px=median(r['reprojection_error_px'] for r in good),
                     first_pose_frame=good[0]['frame_id'], first_pose_s=good[0]['timestamp'],
                     elapsed_s=report['elapsed_s'], source=str(directory.relative_to(ROOT)/'results.json')))
(OUT/'technical_report_data.json').write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')

H, M = [], []
def clean(s):
    return s.replace('־','-').replace('–','-').replace('—','-')
def inline(s):
    s = html.escape(clean(str(s)))
    s = re.sub(r'`([^`]+)`', r'<code dir="ltr">\1</code>', s)
    s = re.sub(r'\*\*([^*]+)\*\*', r'<strong>\1</strong>', s)
    return s
def heading(text, level=2):
    key = f'section-{sum(1 for x in H if x.startswith("<h"))}'
    H.append(f'<h{level} id="{key}">{inline(text)}</h{level}>')
    M.append('#'*level+' '+clean(text)+'\n')
def p(text):
    H.append('<p>'+inline(text)+'</p>')
    M.append(clean(text)+'\n')
def code(text):
    H.append('<pre dir="ltr"><code>'+html.escape(text)+'</code></pre>')
    M.append('```text\n'+text+'\n```\n')
def table(headers, rows):
    H.append('<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+inline(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+inline(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>')
    M.append('| '+' | '.join(headers)+' |\n| '+' | '.join('---' for _ in headers)+' |\n'+''.join('| '+' | '.join(clean(str(x)) for x in row)+' |\n' for row in rows))
def figure(path, caption):
    img = ROOT/path
    assert img.is_file(), img
    uri='data:image/png;base64,'+base64.b64encode(img.read_bytes()).decode('ascii')
    H.append('<figure><img alt="'+html.escape(clean(caption),quote=True)+'" src="'+uri+'"><figcaption>'+inline(caption)+'</figcaption></figure>')
    M.append(f'![{clean(caption)}](../{path})\n\n{clean(caption)}\n')

