totals={k:sum(d[k] for d in data) for k in ('decoded','processed','pose','omitted','losses')}
p(f"בסך הכול נקראו {totals['decoded']:,} פריימים ועובדו {totals['processed']:,}. התקבלו {totals['pose']:,} אומדני Pose שעברו את הבדיקות, והושמטו {totals['omitted']} פריימי מקור. נספרו {totals['losses']} איבודי מעקב. אלה ספירות תפעוליות על סרטונים בעלי תנאים שונים, ואין לפרש את היחס המצטבר כדיוק זיהוי מול אמת מתויגת.")
p('הריצה החדשה של v1 משלימה את הריצה הקודמת שנעצרה לאחר 250 פריימי מקור. כעת נקראו כל 309 הפריימים הניתנים לפענוח, עובדו 289, וב-253 התקבל Pose. לאחר הרכישה בפריים 36 לא נרשם איבוד. נתון ה-FPS הכולל בריצה זו הוא 16.49. קובצי הסקירה הישנים נשמרים כראיה היסטורית; המספרים במסמך זה הם העדכניים.')
table(['ניסוי', 'חציון עיבוד במילישניות', 'חציון השהיה במילישניות', 'חציון RMS בפיקסלי עבודה'], [[d['video'],f"{d['processing_median_ms']:.2f}",f"{d['latency_median_ms']:.2f}",f"{d['rms_median_px']:.3f}"] for d in data])
